from gurobipy import Model, GRB, quicksum

def build_and_solve():
    global LEGACY_RECORDS
    capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
    if not capacity_records or 'Capacity' not in capacity_records[0]['values']:
        raise ValueError('Missing capacity record or field')
    try:
        capacity = int(capacity_records[0]['values']['Capacity'])
    except Exception:
        raise ValueError('Capacity value is not an integer')
    product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
    if len(product_records) != 25:
        raise ValueError('Expected 25 product records, got %d' % len(product_records))
    vehicle_types = []
    value = {}
    weight = {}
    for (idx, rec) in enumerate(product_records):
        vals = rec['values']
        if 'ProductName' not in vals or 'Value' not in vals or 'Weight' not in vals:
            raise ValueError('Missing fields in product record %d' % idx)
        name = vals['ProductName']
        try:
            v = int(vals['Value'])
            w = int(vals['Weight'])
        except Exception:
            raise ValueError('Non-integer Value or Weight in product record %d' % idx)
        vehicle_types.append(name)
        value[name] = v
        weight[name] = w
    for name in vehicle_types:
        if name not in value or name not in weight:
            raise ValueError('Missing value/weight for %s' % name)
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = m.addVars(vehicle_types, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(quicksum((value[name] * x_vars[name] for name in vehicle_types)), GRB.MAXIMIZE)
    m.addConstr(quicksum((weight[name] * x_vars[name] for name in vehicle_types)) <= capacity, name='cap')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print('ObjVal', m.ObjVal)
        for name in vehicle_types:
            print(x_vars[name].VarName, x_vars[name].X)
    else:
        print('Status', m.Status)
    return m
